WITH unpacked AS (SELECT id, level, status_code, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, COALESCE(context['trace'], 'direct') AS trace_or_default, COALESCE(context['version'], 'direct') AS version_or_default FROM app_logs) SELECT level, SIZE(COLLECT_SET(tier)) AS num_tiers, SUM(CASE WHEN tier = 'free' THEN status_code ELSE 0 END) AS free_status_code, COUNT(DISTINCT id) AS distinct_ids FROM unpacked GROUP BY 1 HAVING COUNT(DISTINCT id) > 1;
